import java.util.Scanner;

public class Main {
    static long fn, fd;
    static long ra, rb;

    public static long gcd(long a, long b) {
        if (b == 0)
            return a;
        else
            return gcd(b, a % b);
    }

    public static void function(long x, long y, long b, long a) {
        if (a < 0) {
            return;
        }
        long kkk = gcd(a, b);
        a = a / kkk;
        b = b / kkk;
        long n = Math.abs(b * x - a * y);
        long d = b * y;
        long g = gcd(n, d);
        n = n / g;
        d = d / g;
        if (n * fd < fn * d) {
            fn = n;
            fd = d;
            ra = a;
            rb = b;
            return;
        }
        if (n * fd == d * fn) {
            if (b < rb) {
                ra = a;
                rb = b;
                return;
            }
            if (b > rb) {
                return;
            }
            if (a < ra) {
                ra = a;
                rb = b;
                return;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        fn = 100000;
        fd = 1;
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

